	}
	if _, err := store.Execute("gip-reopen-chain", 10); err != nil {
		t.Fatal(err)
	}
	store.Close()

	// 关闭后重新打开：无须重新创建，多级委托路径直接完整显示，状态与记录保留。
	reopened, err := Open(path)
